const { Readable, Transform } = require('stream');

// 1. The Hose (Readable)
const readableHose = Readable.from(["Node.js ", "Streams ", "Are ", "Awesome!"]);

// 2. The Filter (Transform)
// It adds a star to everything
const starFilter = new Transform({
  transform(chunk, enc, cb) {
    this.push(`⭐ ${chunk.toString()}`);
    cb();
  }
});

// 3. The Pool (Writable - standard output)
const writablePool = process.stdout;

console.log("Connecting the pipes...\n");

// PLUMBING!
// Read -> Filter -> Write
readableHose.pipe(starFilter).pipe(writablePool);

// Output:
// ⭐ Node.js ⭐ Streams ⭐ Are ⭐ Awesome!
